const zlib = require('zlib');

// Segundo argumento: nombre de la propiedad binaria.
// Si falla, mira en el panel de entrada como se llama (suele ser 'data').
const binary = await this.helpers.getBinaryDataBuffer(0, 'data');
const csv = zlib.gunzipSync(binary).toString('utf-8');

const lineas = csv.split('\n');

let scoreDate = null;
const meta = lineas.find(l => l.startsWith('#'));
if (meta) {
  const m = meta.match(/score_date:([0-9T:\-Z]+)/);
  if (m) scoreDate = m[1];
}

const registros = [];
for (const linea of lineas) {
  const l = linea.trim();
  if (!l || l.startsWith('#') || l.startsWith('cve,')) continue;
  const [cve, epss, percentile] = l.split(',');
  if (!cve) continue;
  registros.push({
    json: {
      cve_id: cve,
      epss_score: parseFloat(epss) || 0,
      epss_percentile: parseFloat(percentile) || 0,
      score_date: scoreDate
    }
  });
}

return registros;

const registros = $input.all();
const TAM_LOTE = 5000;
const ES = 'http://elasticsearch:9200';

let indexados = 0;
let errores = 0;
const lotesFallidos = [];

for (let i = 0; i < registros.length; i += TAM_LOTE) {
  const lote = registros.slice(i, i + TAM_LOTE);
  const numLote = Math.floor(i / TAM_LOTE) + 1;

  // Construir el cuerpo NDJSON del _bulk
  let body = '';
  for (const item of lote) {
    const doc = item.json;
    body += JSON.stringify({ index: { _index: 'epss-scores', _id: doc.cve_id } }) + '\n';
    body += JSON.stringify(doc) + '\n';
  }

  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${ES}/_bulk`,
      headers: { 'Content-Type': 'application/x-ndjson' },
      body,
      json: true,
      timeout: 60000,
    });

    // _bulk siempre responde 200 aunque documentos concretos fallen:
    // hay que mirar el flag 'errors' de la respuesta
    if (resp.errors) {
      const fallos = (resp.items || []).filter(it => it.index && it.index.error);
      errores += fallos.length;
      indexados += lote.length - fallos.length;
      if (fallos.length) {
        lotesFallidos.push({ lote: numLote, ejemplo: fallos[0].index.error });
      }
    } else {
      indexados += lote.length;
    }
  } catch (e) {
    errores += lote.length;
    lotesFallidos.push({ lote: numLote, error: e.message });
  }
}

return [{
  json: {
    total: registros.length,
    indexados,
    errores,
    lotes_fallidos: lotesFallidos.slice(0, 5),
    ok: errores === 0
  }
}];
